window.VOIX_ADD&&window.VOIX_ADD({"interesser-0": {"t": "Moi, ce week-end, j’ai fait de la piscine !", "src": "data:audio/mpeg;base64,"}, "interesser-1": {"t": "Et toi, qu’est-ce que tu as fait ?", "src": "data:audio/mpeg;base64,"}, "interesser-2": {"t": "Je suis allé chez mon papy, à la ferme. Il y avait des lapins !", "src": "data:audio/mpeg;base64,"}, "interesser-3": {"t": "Trop bien ! Ils s’appellent comment ?", "src": "data:audio/mpeg;base64,"}, "interesser-4": {"t": "Caramel et Noisette ! Merci de me demander.", "src": "data:audio/mpeg;base64,"}, "interesser-pourquoi": {"t": "Quand je pose une question à l'autre, il sent qu'il compte pour moi. Je découvre plein de choses sur lui, et on devient encore plus copains. Parler, c'est comme jouer à la balle : je la lance, puis je la renvoie !", "src": "data:audio/mpeg;base64,"}});
